/*
 Problem: 2904. Shortest and Lexicographically Smallest Beautiful String
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.9 MB (48.03%)
 Tags: String, Sliding Window
*/
class Solution {
public:
    string shortestBeautifulSubstring(string s, int k) {
        int l = 0, cnt = 0;
        string ans;

        for (int r = 0; r < s.size(); r++) {
            cnt += s[r] == '1';

            while (cnt > k)
                cnt -= s[l++] == '1';

            if (cnt == k) {
                while (s[l] == '0') l++;
                string t = s.substr(l, r - l + 1);

                if (ans.empty() || t.size() < ans.size() ||
                    t.size() == ans.size() && t < ans)
                    ans = t;
            }
        }

        return ans;
    }
};
